import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Scissors } from "lucide-react";
import { Slider } from "@/components/ui/slider";

const RAW_TOKENS = 45120;
const SAVINGS = { 1: 0.62, 2: 0.74, 3: 0.83 };
const LEVEL_LABELS = { 1: "Conservative", 2: "Balanced", 3: "Surgical" };

const RAW_LINES = [
  { t: "$ npm run test -- --coverage", c: "text-zinc-300" },
  { t: "............................................", c: "text-zinc-600" },
  { t: "............................................", c: "text-zinc-600" },
  { t: "............................................", c: "text-zinc-600" },
  { t: "········ 2,812 lines of suite noise ········", c: "text-zinc-700" },
  { t: "FAIL src/payments/refund.test.ts", c: "text-red-400" },
  { t: "  ● processRefund › rejects duplicate txn", c: "text-red-400" },
  { t: "    Expected: 409 Conflict", c: "text-zinc-500" },
  { t: "    Received: 500 Internal Server Error", c: "text-zinc-500" },
  { t: "+ 2,847 more lines…", c: "text-zinc-600" },
];

const TRIMMED_LINES = [
  { t: "$ npm run test -- --coverage", c: "text-zinc-300" },
  { t: "[tokenbrake] collapsed 2,812 passing lines", c: "text-emerald-400" },
  { t: "FAIL src/payments/refund.test.ts:47", c: "text-red-400" },
  { t: "  ● processRefund › rejects duplicate txn", c: "text-red-400" },
  { t: "    Expected: 409 · Received: 500", c: "text-zinc-400" },
  { t: "  at processRefund (src/payments/refund.ts:112)", c: "text-zinc-500" },
  { t: "[tokenbrake] stack trace + error context kept", c: "text-emerald-400" },
];

const fmt = (n) => n.toLocaleString("en-US");

export default function TrimSimulator() {
  const [mode, setMode] = useState("trimmed");
  const [level, setLevel] = useState([2]);
  const pct = SAVINGS[level[0]];
  const trimmed = Math.round(RAW_TOKENS * (1 - pct));

  return (
    <div
      className="overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-[0_24px_60px_-24px_rgba(9,9,11,0.18)]"
      data-testid="trim-simulator"
    >
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-zinc-200 px-5 py-3.5">
        <div className="flex items-center gap-2 rounded-lg bg-zinc-100 p-1" role="tablist" aria-label="Output mode">
          {["raw", "trimmed"].map((m) => (
            <button
              key={m}
              role="tab"
              aria-selected={mode === m}
              onClick={() => setMode(m)}
              className={`rounded-md px-3.5 py-1.5 font-mono text-xs font-semibold transition-all duration-200 ${
                mode === m
                  ? m === "trimmed"
                    ? "bg-emerald-600 text-white shadow-sm"
                    : "bg-zinc-950 text-white shadow-sm"
                  : "text-zinc-500 hover:text-zinc-900"
              }`}
              data-testid={`trim-simulator-toggle-${m}`}
            >
              {m === "raw" ? "Raw output" : "Tokenbrake"}
            </button>
          ))}
        </div>
        <span className="flex items-center gap-1.5 font-mono text-xs text-zinc-400">
          <Scissors className="h-3.5 w-3.5 text-emerald-600" />
          live trim simulator
        </span>
      </div>

      <div className="relative min-h-[264px] bg-zinc-950 p-5">
        <AnimatePresence mode="wait">
          <motion.div
            key={mode}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.28, ease: "easeOut" }}
            className="font-mono text-[12.5px] leading-[1.75]"
            data-testid="trim-simulator-output"
          >
            {(mode === "raw" ? RAW_LINES : TRIMMED_LINES).map((l, i) => (
              <div key={i} className={l.c}>
                {l.t}
              </div>
            ))}
          </motion.div>
        </AnimatePresence>
      </div>

      <div className="border-t border-zinc-200 px-5 py-4">
        <div className="flex items-center justify-between gap-4">
          <label className="font-mono text-xs text-zinc-500" htmlFor="trim-aggressiveness">
            trim aggressiveness · <span className="font-semibold text-zinc-800">{LEVEL_LABELS[level[0]]}</span>
          </label>
          <div className="flex gap-4 font-mono text-xs">
            <span className="text-zinc-400">
              raw <span className="font-semibold text-zinc-700">{fmt(RAW_TOKENS)}</span>
            </span>
            <span className="text-zinc-400">
              sent <span className="font-semibold text-emerald-700">{fmt(trimmed)}</span>
            </span>
          </div>
        </div>
        <Slider
          id="trim-aggressiveness"
          min={1}
          max={3}
          step={1}
          value={level}
          onValueChange={setLevel}
          className="mt-3"
          aria-label="Trim aggressiveness"
          data-testid="trim-aggressiveness-slider"
        />
        <div className="mt-4 flex items-end justify-between">
          <motion.span
            key={pct}
            initial={{ scale: 0.85, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ type: "spring", stiffness: 260, damping: 18 }}
            className="font-mono text-4xl font-semibold tracking-tight text-emerald-600"
            data-testid="trim-savings-value"
          >
            −{Math.round(pct * 100)}%
          </motion.span>
          <span className="pb-1 font-mono text-xs text-zinc-400">tokens saved this tool call</span>
        </div>
      </div>
    </div>
  );
}
