import { useState } from "react";
import { motion } from "framer-motion";
import { Check, Copy, Terminal } from "lucide-react";
import { toast } from "sonner";
import { copyText } from "./Reveal";

export default function CodeBlock({ title, code, testid, dark = true }) {
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    const ok = await copyText(code);
    if (ok) {
      setCopied(true);
      toast.success("Command copied to clipboard");
      setTimeout(() => setCopied(false), 1600);
    } else {
      toast.error("Copy failed — select the text manually");
    }
  };

  return (
    <div
      className="overflow-hidden rounded-xl border border-zinc-800 bg-zinc-950 shadow-sm"
      data-testid={testid}
    >
      <div className="flex items-center justify-between border-b border-zinc-800/80 px-4 py-2.5">
        <div className="flex items-center gap-2.5">
          <span className="flex gap-1.5">
            <i className="h-2.5 w-2.5 rounded-full bg-zinc-700" />
            <i className="h-2.5 w-2.5 rounded-full bg-zinc-700" />
            <i className="h-2.5 w-2.5 rounded-full bg-emerald-500/80" />
          </span>
          <span className="flex items-center gap-1.5 font-mono text-xs text-zinc-500">
            <Terminal className="h-3.5 w-3.5" />
            {title}
          </span>
        </div>
        <motion.button
          whileTap={{ scale: 0.88 }}
          onClick={copy}
          className="flex items-center gap-1.5 rounded-md border border-zinc-800 bg-zinc-900 px-2 py-1 font-mono text-xs text-zinc-400 transition-colors hover:border-emerald-500/50 hover:text-emerald-400"
          aria-label={`Copy ${title}`}
          data-testid={`${testid}-copy-btn`}
        >
          {copied ? <Check className="h-3.5 w-3.5 text-emerald-400" /> : <Copy className="h-3.5 w-3.5" />}
          {copied ? "copied" : "copy"}
        </motion.button>
      </div>
      <pre className="overflow-x-auto p-4 font-mono text-[13px] leading-relaxed text-zinc-200">
        <code>{code}</code>
      </pre>
    </div>
  );
}
