import { Asterisk } from "lucide-react";

const ITEMS = [
  "Surgical tool-output trimming",
  "Bounded file reads",
  "Zero-latency local interception",
  "Claude Code native compatibility",
  "Real-time token consumption auditing",
  "Prevent context window collapse",
  "100% private & offline",
];

export default function Marquee() {
  const row = (ariaHidden) => (
    <div className="flex shrink-0 items-center" aria-hidden={ariaHidden}>
      {ITEMS.map((item) => (
        <span
          key={item + (ariaHidden ? "-b" : "-a")}
          className="flex items-center gap-8 pr-8 font-mono text-xs font-medium uppercase tracking-[0.22em] text-zinc-500"
        >
          {item}
          <Asterisk className="h-4 w-4 text-emerald-500" />
        </span>
      ))}
    </div>
  );

  return (
    <div
      className="group overflow-hidden border-y border-zinc-200 bg-white py-4"
      data-testid="editorial-marquee"
      role="marquee"
      aria-label="Tokenbrake capabilities"
    >
      <div className="flex w-max animate-marquee group-hover:[animation-play-state:paused]">
        {row(false)}
        {row(true)}
      </div>
    </div>
  );
}
