import { useState } from "react";
import { Link, NavLink, useLocation } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { Github, Menu, X, ArrowUpRight } from "lucide-react";
import LogoMark from "./LogoMark";

const LINKS = [
  { label: "Features", to: "/#features", testid: "nav-link-features" },
  { label: "How It Works", to: "/#how-it-works", testid: "nav-link-how-it-works" },
  { label: "Architecture", to: "/#architecture", testid: "nav-link-architecture" },
  { label: "Docs", to: "/docs", testid: "nav-link-docs" },
  { label: "About", to: "/about", testid: "nav-link-about" },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const { pathname } = useLocation();

  const linkClass = (to) => {
    const active = to === pathname && !to.includes("#");
    return `text-sm font-medium transition-colors duration-200 ${
      active ? "text-emerald-700" : "text-zinc-600 hover:text-zinc-950"
    }`;
  };

  return (
    <header className="sticky top-0 z-50 border-b border-zinc-200/80 bg-white/80 backdrop-blur-md" data-testid="navbar">
      <nav className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6 lg:px-8">
        <Link to="/" className="group flex items-center gap-2.5" data-testid="nav-logo" aria-label="Tokenbrake home">
          <LogoMark className="h-8 w-8 rounded-[9px] transition-transform duration-300 group-hover:-rotate-6" />
          <span className="font-mono text-[15px] font-semibold tracking-tight text-zinc-950">
            tokenbrake<span className="animate-pulse-dot text-emerald-600">_</span>
          </span>
        </Link>

        <div className="hidden items-center gap-7 md:flex">
          {LINKS.map((l) =>
            l.to.startsWith("/#") ? (
              <Link key={l.to} to={l.to} className={linkClass(l.to)} data-testid={l.testid}>
                {l.label}
              </Link>
            ) : (
              <NavLink key={l.to} to={l.to} className={linkClass(l.to)} data-testid={l.testid}>
                {l.label}
              </NavLink>
            ),
          )}
        </div>

        <div className="hidden items-center gap-3 md:flex">
          <a
            href="https://github.com/33kain/tokenbrake"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 rounded-lg border border-zinc-300 bg-white px-3.5 py-2 text-sm font-medium text-zinc-800 transition-all duration-200 hover:border-zinc-950 hover:text-zinc-950"
            data-testid="nav-github-link"
          >
            <Github className="h-4 w-4" />
            Star
          </a>
          <Link
            to="/docs"
            className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-3.5 py-2 text-sm font-semibold text-white shadow-sm transition-all duration-200 hover:bg-emerald-700 hover:shadow-md"
            data-testid="nav-quickstart-btn"
          >
            Quickstart
            <ArrowUpRight className="h-4 w-4" />
          </Link>
        </div>

        <button
          className="inline-flex h-10 w-10 items-center justify-center rounded-lg border border-zinc-200 text-zinc-700 md:hidden"
          onClick={() => setOpen((v) => !v)}
          aria-label={open ? "Close menu" : "Open menu"}
          aria-expanded={open}
          data-testid="nav-mobile-toggle"
        >
          {open ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
        </button>
      </nav>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="overflow-hidden border-t border-zinc-200 bg-white md:hidden"
            data-testid="nav-mobile-menu"
          >
            <div className="space-y-1 px-4 py-4">
              {LINKS.map((l) => (
                <Link
                  key={l.to}
                  to={l.to}
                  onClick={() => setOpen(false)}
                  className="block rounded-lg px-3 py-2.5 text-sm font-medium text-zinc-700 hover:bg-zinc-100"
                  data-testid={`${l.testid}-mobile`}
                >
                  {l.label}
                </Link>
              ))}
              <a
                href="https://github.com/33kain/tokenbrake"
                target="_blank"
                rel="noopener noreferrer"
                className="mt-2 flex items-center justify-center gap-2 rounded-lg bg-zinc-950 px-3 py-2.5 text-sm font-semibold text-white"
                data-testid="nav-github-link-mobile"
              >
                <Github className="h-4 w-4" />
                Star on GitHub
              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}
